    'appdl.heroTitle': 'Emergency chat that works when networks don’t',
    'appdl.heroDesc': 'SOA Mesh is the Android companion to AapdaSetu. Nearby phones relay SOS and text messages device-to-device over Bluetooth, so your words can hop across phones around you even when cell towers and the internet are completely down.',
